 c=copy.deepcopy(candidate);hid=f'A1A2-PILOT-{suffix}';reviewer={'actor_id':'UNITALK-SEVERINE-STEP8','actor_role':'Unitalk Operations A2 Pilot Reviewer','display_name':'Séverine'};c['workflow']={'stage':'approved_for_a2','review_decision':'approved','reviewer':reviewer,'decision_at':APPROVED_AT,'rejection_reason':None};c['recommendation']['next_action']='pass_to_a2';c['recommendation']['notes']='Authorised by Séverine for the bounded Step 8 A2 pilot. This is a Unitalk test authorisation, not outreach or CRM-write approval.';c['updated_at']=APPROVED_AT;c['system_references']['a2_handoff_id']=hid
