 src=load(SOURCE);index={x['candidate_id']:x['prospect_candidate'] for x in src['candidates']};OUT.mkdir(parents=True,exist_ok=True);results=[]
 for cid,suffix in TARGETS.items():
  doc=build(index[cid],suffix);path=OUT/f'{cid}.handoff.json';path.write_text(json.dumps(doc,indent=2,ensure_ascii=False)+'\n');validation=validate_document(path);results.append({'candidate_id':cid,'handoff_id':doc['handoff_id'],'path':str(path.relative_to(ROOT)),'sha256':sha(path),'valid':validation['valid'],'eligibility':doc['eligibility']['status'],'errors':validation['errors']})
